python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=5);o=r.get_obs(include_depth=True,video='none');d=o.depth['right_camera'][0].astype(float);K=np.array(o.meta['cameras']['right_camera']['intrinsic_cv']);E=np.array(o.meta['cameras']['right_camera']['extrinsic_cv']);R=E[:,:3];t=E[:,3];
def pt(u,v):
 z=d[v,u]/1000.; c=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z]);w=np.linalg.inv(R)@(c-t);return round(d[v,u],1),np.round(w,3)
for uv in [(100,180),(220,120),(240,120),(260,120),(280,180),(300,220),(245,35),(245,80)]:print(uv,pt(*uv))
print('E',E)
PY

